CREATE TEMP TABLE nov9_changes ON COMMIT DROP AS SELECT id,home_team_id,away_team_id FROM jsonb_populate_recordset(null::public.fixtures,'[{"id":"12fa288c-08f6-4f65-b75b-e5c48b12872c","home_team_id":"d16662f1-9520-4f2a-b30b-ede1db30f28d","away_team_id":"e5b8d7c3-89e1-430a-94b4-afd7b42cbe43"},{"id":"a6d024dc-c03a-4f2f-8c5f-db8d35dd801d","home_team_id":"bd834936-1b8a-4dd7-9013-d4b792862b67","away_team_id":"997291fd-33ff-40cc-9fd8-be732f6e07ca"},{"id":"930fc39c-a227-410e-94cf-8b99cc6ba56c","home_team_id":"38580a95-ab89-5ddd-a71d-c31ed05de4bd","away_team_id":"3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff"},{"id":"5a0e2b47-3351-58e6-a9fe-b69200a94fb5","home_team_id":"8464062e-5897-4573-a075-d283236dd36c","away_team_id":"57b0b3f9-24a5-4ea7-9e1b-fd3faa90891c"},{"id":"0638c88d-ff1e-419c-88d6-a9efebdead2d","home_team_id":"3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff","away_team_id":"bd834936-1b8a-4dd7-9013-d4b792862b67"},{"id":"d9f713df-b04c-4d09-adf3-2aa174fa9c80","home_team_id":"997291fd-33ff-40cc-9fd8-be732f6e07ca","away_team_id":"d16662f1-9520-4f2a-b30b-ede1db30f28d"},{"id":"c76a8458-67ad-4093-8728-a571d40f59eb","home_team_id":"44d7e359-957a-4b38-8a0a-40b698d609c9","away_team_id":"b78bd03e-1e87-4cf7-8a0e-409f5de92959"},{"id":"e39ac729-005d-42aa-94b5-6d7c13593afb","home_team_id":"38580a95-ab89-5ddd-a71d-c31ed05de4bd","away_team_id":"e5b8d7c3-89e1-430a-94b4-afd7b42cbe43"},{"id":"21057a98-6243-4d69-98ef-5fe1e0ed3629","home_team_id":"d16662f1-9520-4f2a-b30b-ede1db30f28d","away_team_id":"44d7e359-957a-4b38-8a0a-40b698d609c9"},{"id":"a7ac2a09-accf-4553-b7b2-4feae7b249bc","home_team_id":"57b0b3f9-24a5-4ea7-9e1b-fd3faa90891c","away_team_id":"8464062e-5897-4573-a075-d283236dd36c"},{"id":"c7fb6499-7278-471a-893a-abb86d9dfa3d","home_team_id":"e5b8d7c3-89e1-430a-94b4-afd7b42cbe43","away_team_id":"d16662f1-9520-4f2a-b30b-ede1db30f28d"},{"id":"705a852b-c4ed-4b2d-aefb-4585f7d96aac","home_team_id":"d16662f1-9520-4f2a-b30b-ede1db30f28d","away_team_id":"997291fd-33ff-40cc-9fd8-be732f6e07ca"},{"id":"a5f67148-9add-512d-9859-19e4e693ab94","home_team_id":"38580a95-ab89-5ddd-a71d-c31ed05de4bd","away_team_id":"44d7e359-957a-4b38-8a0a-40b698d609c9"},{"id":"6f79837f-2ead-4ebf-bc95-280677f21988","home_team_id":"b78bd03e-1e87-4cf7-8a0e-409f5de92959","away_team_id":"3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff"},{"id":"5b9c8bdf-33e5-43db-8f8a-e500ddaf94f5","home_team_id":"bd834936-1b8a-4dd7-9013-d4b792862b67","away_team_id":"57b0b3f9-24a5-4ea7-9e1b-fd3faa90891c"},{"id":"35f34712-2bd5-468f-9899-a2b6c9a414b8","home_team_id":"3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff","away_team_id":"8464062e-5897-4573-a075-d283236dd36c"}]'::jsonb);
CREATE TEMP TABLE nov9_results ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"fixture_id":"168ca6fe-a6ce-4023-9c29-629c31a05658","result_id":"5d50f4bf-6df1-428e-a5b9-2643e22e567c","home_score":7,"away_score":3},{"fixture_id":"12fa288c-08f6-4f65-b75b-e5c48b12872c","result_id":"63d1f6c9-37fd-49be-aa68-06826c8f7eee","home_score":6,"away_score":6},{"fixture_id":"a6d024dc-c03a-4f2f-8c5f-db8d35dd801d","result_id":"c6e91653-c411-4d4c-bce3-550a421c3be1","home_score":5,"away_score":0},{"fixture_id":"a08361d7-29fc-4035-9fbb-c1c3a475a077","result_id":"3af3c252-1e8e-42ba-a231-192882707112","home_score":5,"away_score":6},{"fixture_id":"930fc39c-a227-410e-94cf-8b99cc6ba56c","result_id":"152f1c46-3cb0-4889-9c4d-301be6b5a6f3","home_score":3,"away_score":6},{"fixture_id":"f43c6052-360e-4b25-b8ba-147baaed1af2","result_id":"058175da-7006-4ed5-8954-a894fdaf332c","home_score":10,"away_score":2},{"fixture_id":"5a0e2b47-3351-58e6-a9fe-b69200a94fb5","result_id":"6c064f93-6939-4126-8eba-131e0170e066","home_score":8,"away_score":3},{"fixture_id":"0a525e06-20f0-4a4a-95da-d22f986f77c5","result_id":"e89a648c-a5a9-4a6c-9b8d-a3713077b653","home_score":3,"away_score":9}]'::jsonb)AS x(fixture_id uuid,result_id uuid,home_score integer,away_score integer);
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.competition_seasons WHERE id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND lifecycle='active' AND publication_state='published')THEN RAISE EXCEPTION 'Monday edition changed';END IF;
 IF EXISTS(SELECT 1 FROM public.fixture_change_sets WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND status IN('draft','pending_review'))THEN RAISE EXCEPTION 'Review pending fixture work first';END IF;
 IF (SELECT count(*)FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled')<>240 OR EXISTS(SELECT 1 FROM nov9_baseline b LEFT JOIN public.fixtures f USING(id)WHERE row(f.id,f.competition_season_id,f.legacy_id,f.round_number,f.round_label,f.match_date,f.kickoff_time,f.court,f.home_team_id,f.away_team_id,f.schedule_version,f.updated_at,f.publication_state,f.schedule_status,f.stage)IS DISTINCT FROM row(b.id,b.competition_season_id,b.legacy_id,b.round_number,b.round_label,b.match_date,b.kickoff_time,b.court,b.home_team_id,b.away_team_id,b.schedule_version,b.updated_at,b.publication_state,b.schedule_status,b.stage))THEN RAISE EXCEPTION 'Monday schedule baseline changed';END IF;
 IF (SELECT count(*)FROM public.teams WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND status='active' AND standings_eligible)<>16 THEN RAISE EXCEPTION 'Monday roster changed';END IF;
 IF EXISTS(SELECT 1 FROM public.result_versions WHERE fixture_id IN(SELECT fixture_id FROM nov9_results) OR fixture_id IN(SELECT id FROM nov9_changes) OR id IN(SELECT result_id FROM nov9_results))THEN RAISE EXCEPTION 'Result work already exists; stop, do not duplicate';END IF;
END $$;
CREATE TEMP TABLE nov9_protected ON COMMIT DROP AS select 'fixtures'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.fixtures x where id not in(select id from nov9_changes)
union all
select 'results'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.result_versions x where true
union all
select 'teams'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.teams x where true
union all
select 'notes'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by team_id)::text,'[]'))hash from public.team_fixture_notes x where true
union all
select 'preferences'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.team_kickoff_preferences x where true
union all
select 'adjustments'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.standing_adjustments x where true
union all
select 'editions'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.competition_seasons x where true
union all
select 'seasons'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.seasons x where true;
CREATE TEMP TABLE nov9_audit_before ON COMMIT DROP AS SELECT id,to_jsonb(a)preserved FROM public.admin_audit_log a;
CREATE TEMP TABLE nov9_fixture_before ON COMMIT DROP AS SELECT id,to_jsonb(f)-'home_team_id'-'away_team_id'-'schedule_version'-'updated_at'preserved,schedule_version FROM public.fixtures f WHERE id IN(SELECT id FROM nov9_changes);
UPDATE public.fixtures f SET home_team_id=c.home_team_id,away_team_id=c.away_team_id FROM nov9_changes c WHERE f.id=c.id;
INSERT INTO public.result_versions(id,fixture_id,revision,status,home_score,away_score) SELECT result_id,fixture_id,1,'published',home_score,away_score FROM nov9_results;
DO $$ BEGIN
 IF (SELECT count(*)FROM nov9_results p JOIN public.result_versions v ON v.id=p.result_id AND v.fixture_id=p.fixture_id AND v.home_score=p.home_score AND v.away_score=p.away_score AND v.revision=1 AND v.status='published' AND v.published_at IS NOT NULL AND v.forfeit_side IS NULL)<>8 THEN RAISE EXCEPTION 'Eight-result verification failed';END IF;
 IF EXISTS(SELECT least(home_team_id,away_team_id),greatest(home_team_id,away_team_id)FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled' GROUP BY 1,2 HAVING count(*)<>2)THEN RAISE EXCEPTION 'Each pair must meet twice';END IF;
 IF EXISTS(SELECT round_number,t FROM public.fixtures f CROSS JOIN LATERAL unnest(array[f.home_team_id,f.away_team_id])t WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled' GROUP BY round_number,t HAVING count(*)<>1)THEN RAISE EXCEPTION 'Team duplicated within round';END IF;
 IF EXISTS(SELECT t FROM public.fixtures f CROSS JOIN LATERAL unnest(array[f.home_team_id,f.away_team_id])t WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled' GROUP BY t HAVING count(*)<>30 OR count(*)FILTER(WHERE home_team_id=t)<>15)THEN RAISE EXCEPTION '30 matches and 15 home required';END IF;
 IF EXISTS(SELECT 1 FROM public.fixtures f JOIN public.teams t ON t.id IN(f.home_team_id,f.away_team_id)WHERE f.competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND f.publication_state='published' AND f.schedule_status='scheduled' AND ((t.name='Blue Dragons'AND f.kickoff_time='19:00')OR(t.name='Bunyip'AND f.kickoff_time NOT IN('19:00','19:40'))))THEN RAISE EXCEPTION 'Hard kickoff rule violated';END IF;
 IF EXISTS(SELECT f.round_number,f.kickoff_time FROM public.fixtures f WHERE f.competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND f.publication_state='published' AND f.schedule_status='scheduled' AND (home_team_id IN('d16662f1-9520-4f2a-b30b-ede1db30f28d','997291fd-33ff-40cc-9fd8-be732f6e07ca')OR away_team_id IN('d16662f1-9520-4f2a-b30b-ede1db30f28d','997291fd-33ff-40cc-9fd8-be732f6e07ca'))GROUP BY f.round_number,f.kickoff_time HAVING count(*)>1)THEN RAISE EXCEPTION 'Goldlink/Buckle simultaneous kickoff';END IF;
 IF EXISTS(SELECT 1 FROM nov9_fixture_before b JOIN public.fixtures f USING(id)WHERE b.preserved IS DISTINCT FROM to_jsonb(f)-'home_team_id'-'away_team_id'-'schedule_version'-'updated_at' OR f.schedule_version<>b.schedule_version+1)THEN RAISE EXCEPTION 'Unapproved fixture field/version change';END IF;
 IF EXISTS(SELECT 1 FROM nov9_audit_before b LEFT JOIN public.admin_audit_log a USING(id)WHERE b.preserved IS DISTINCT FROM to_jsonb(a))THEN RAISE EXCEPTION 'Old audit history changed';END IF;
 IF EXISTS(SELECT 1 FROM nov9_protected p JOIN(select 'fixtures'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.fixtures x where id not in(select id from nov9_changes)
union all
select 'results'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.result_versions x where id not in(select result_id from nov9_results)
union all
select 'teams'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.teams x where true
union all
select 'notes'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by team_id)::text,'[]'))hash from public.team_fixture_notes x where true
union all
select 'preferences'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.team_kickoff_preferences x where true
union all
select 'adjustments'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.standing_adjustments x where true
union all
select 'editions'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.competition_seasons x where true
union all
select 'seasons'kind,md5(coalesce(jsonb_agg(to_jsonb(x)order by id)::text,'[]'))hash from public.seasons x where true)a USING(kind)WHERE p.hash IS DISTINCT FROM a.hash)THEN RAISE EXCEPTION 'Protected records changed';END IF;
END $$;
COMMIT;
